package run.ikaros.game; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; import run.ikaros.resource.CreateResourceRequest; import run.ikaros.resource.ResourceService; import run.ikaros.resource.ResourceType; import run.ikaros.storage.AttachmentRepository;
@Service public class PersistentGameArchiveService implements GameArchiveService{private final ResourceService resources;private final GameRepository games;private final GamePlatformRepository platforms;private final GameVersionRepository versions;private final GameAssetRepository assets;private final AttachmentRepository attachments;public PersistentGameArchiveService(ResourceService r,GameRepository g,GamePlatformRepository p,GameVersionRepository v,GameAssetRepository a,AttachmentRepository at){resources=r;games=g;platforms=p;versions=v;assets=a;attachments=at;}
 @Override public Mono<GameView> createGame(UUID o,CreateGameRequest r){String l=r.locale()==null||r.locale().isBlank()?"en-US":r.locale();return resources.create(o,new CreateResourceRequest(ResourceType.GAME,r.title(),l)).flatMap(x->games.save(new GameEntity(null,o,x.id(),r.gameKind(),null))).map(this::gameView);}@Override public Flux<GameView> games(UUID o){return games.findAllByOwnerId(o).map(this::gameView);}@Override public Mono<GamePlatformView> createPlatform(UUID o,CreateGamePlatformRequest r){return platforms.save(new GamePlatformEntity(null,o,r.name().trim(),r.family(),r.architecture())).map(this::platformView);}@Override public Flux<GamePlatformView> platforms(UUID o){return platforms.findAllByOwnerIdOrderByNameAsc(o).map(this::platformView);}@Override public Mono<GameVersionView> createVersion(UUID o,UUID id,CreateGameVersionRequest r){return ownedGame(o,id).flatMap(g->(r.platformId()==null?Mono.just((GamePlatformEntity)null):platforms.findById(r.platformId()).filter(p->p.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Platform 不存在或无权访问")))).flatMap(p->versions.save(new GameVersionEntity(null,o,id,p==null?null:p.id(),r.versionLabel(),r.releaseDate(),null)))).map(this::versionView);}@Override public Flux<GameVersionView> versions(UUID o,UUID id){return ownedGame(o,id).flatMapMany(g->versions.findAllByOwnerIdAndGameId(o,id).map(this::versionView));}@Override public Mono<GameAssetView> addAsset(UUID o,UUID id,CreateGameAssetRequest r){return ownedGame(o,id).flatMap(g->attachments.findByIdAndResourceIdAndDeletedAtIsNull(r.attachmentId(),g.resourceId()).switchIfEmpty(Mono.error(new NotFoundException("Asset Attachment 不属于 Game Resource"))).then(assets.save(new GameAssetEntity(null,o,id,r.versionId(),r.attachmentId(),r.category(),r.displayName(),r.checksumAlgorithm(),r.checksumValue(),GameAssetAvailability.AVAILABLE,null)))).map(this::assetView);}@Override public Flux<GameAssetView> assets(UUID o,UUID id){return ownedGame(o,id).flatMapMany(g->assets.findAllByOwnerIdAndGameId(o,id).map(this::assetView));}@Override public Mono<GameAssetView> availability(UUID o,UUID id,UpdateGameAssetAvailabilityRequest r){return assets.findById(id).filter(a->a.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Game Asset 不存在或无权访问"))).flatMap(a->assets.save(new GameAssetEntity(a.id(),a.ownerId(),a.gameId(),a.versionId(),a.attachmentId(),a.category(),a.displayName(),a.checksumAlgorithm(),a.checksumValue(),r.availability(),a.entityVersion()))).map(this::assetView);}
 private Mono<GameEntity> ownedGame(UUID o,UUID id){return games.findById(id).filter(g->g.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Game 不存在或无权访问")));}private GameView gameView(GameEntity e){return new GameView(e.id(),e.resourceId(),e.gameKind());}private GamePlatformView platformView(GamePlatformEntity e){return new GamePlatformView(e.id(),e.name(),e.family(),e.architecture());}private GameVersionView versionView(GameVersionEntity e){return new GameVersionView(e.id(),e.gameId(),e.platformId(),e.versionLabel(),e.releaseDate());}private GameAssetView assetView(GameAssetEntity e){return new GameAssetView(e.id(),e.gameId(),e.versionId(),e.attachmentId(),e.category(),e.displayName(),e.checksumAlgorithm(),e.checksumValue(),e.availability());}}
